// Agent-written development cases. Manually authored for parser verification, never for model training.
// The groups describe the wording of the request. They do not infer anything about the speaker.
import type { QuestionShape } from '../../apps/server/src/assistant/understanding/question-shape.js';

export type QuestionGroup = 'Egyptian' | 'Gulf' | 'Levantine' | 'Iraqi' | 'Maghrebi' | 'Arabizi' | 'MSA' | 'English';
export interface DevelopmentQuestion {
  group: QuestionGroup;
  text: string;
  questionWord: string | null;
  answerType: QuestionShape['answerType'] | null;
}
type QuestionRow = [QuestionShape['answerType'] | null, string | null, ...string[]];

function cases(group: QuestionGroup, rows: QuestionRow[]): DevelopmentQuestion[] {
  return rows.flatMap(([answerType, questionWord, ...texts]) => texts.map(text => ({ group, text, questionWord, answerType })));
}

